#include <Wire.h>
#include <LiquidCrystal_I2C.h>

LiquidCrystal_I2C lcd(0x27,16,2);

int num;

void setup() {

  Serial.begin(9600);

  lcd.init();
  lcd.backlight();

  lcd.print("Press S");
}

void loop() {

  if (Serial.available()) {

    char a = Serial.read();

    if (a == 's') {

      num = random(1,11);

      lcd.clear();
      lcd.print("Guess 1-10");
    }

    if (a == '1') {

      lcd.clear();

      if (1 < num) {
        lcd.print("Low");
      }

      else if (1 > num) {
        lcd.print("High");
      }

      else {
        lcd.print("Correct");
      }
    }

    if (a == '2') {

      lcd.clear();

      if (2 < num) {
        lcd.print("Low");
      }

      else if (2 > num) {
        lcd.print("High");
      }

      else {
        lcd.print("Correct");
      }
    }

  }

}

