void setup()
{
  pinMode(7, INPUT);
  pinMode(3, INPUT);
  pinMode(4, OUTPUT);
  pinMode(2, OUTPUT);

  Serial.begin(9600);
}

void loop()
{
  if (digitalRead(7) == LOW)
  {
    Serial.println("RED LIGHT ACTIVATED");
    digitalWrite(4, HIGH);
    digitalWrite(2, LOW);
    delay(1000);
  }
  else
  {
    if (digitalRead(3) == LOW)
    {
      Serial.println("GREEN LIGHT ACTIVATED");
      digitalWrite(2, HIGH);
      digitalWrite(4, LOW);
      delay(1000);
    }
  }
}
